noncomputable def Def7 (F : ArithmeticTheory) [F.RE] : ArithmeticSentence := F.craig.consistent.val

def Def8 (K : Def1) (F : ArithmeticTheory) [F.RE] : Prop :=
  Def5 K F ∧ Def7 F ∈ K

def Def9 (K : Def1) (F : ArithmeticTheory) [F.RE] : Prop :=
  F.craig.localReflectionOn Set.univ ⊆ K

